import os

from typing import TYPE_CHECKING

if TYPE_CHECKING:
    from typing_extensions import TypedDict, Literal, Final, NotRequired, TypeIs
elif os.environ.get("J2PY_FORCE_MOCKS"):
    # Debug/test: force mocking types
    from .typing_mocks import TypedDict, Literal, Final, NotRequired, TypeIs
    if os.environ.get("J2PY_DEBUG"):
        print("[J2PY] Using own mocks (forced)")
else:
    # Check if TypedDict with generics works
    try:
        from typing import Generic as _Generic, TypeVar as _TypeVar
        try:
            from typing_extensions import TypedDict as _TypedDict
        except Exception:
            from typing import TypedDict as _TypedDict
        T = _TypeVar("T")
        class A(_Generic[T], _TypedDict):
            pass
        TypedDict = _TypedDict
    except Exception:
        from .typing_mocks import TypedDict

    try:
        try:
            from typing_extensions import NotRequired as _NotRequired
        except Exception:
            from typing import NotRequired as _NotRequired
        NotRequired = _NotRequired
    except Exception:
        from .typing_mocks import NotRequired

    try:
        try:
            from typing_extensions import Literal as _Literal
        except Exception:
            from typing import Literal as _Literal
        Literal = _Literal
    except Exception:
        from .typing_mocks import Literal

    try:
        try:
            from typing_extensions import Final as _Final
        except Exception:
            from typing import Final as _Final
        Final = _Final
    except Exception:
        from .typing_mocks import Final

    try:
        try:
            from typing_extensions import TypeIs as _TypeIs
        except Exception:
            from typing import TypeIs as _TypeIs
        TypeIs = _TypeIs
    except Exception:
        from .typing_mocks import TypeIs

if os.environ.get("J2PY_DEBUG"):
    print("[J2PY] Use TypedDict from %s" % TypedDict.__module__)
    print("[J2PY] Use NotRequired from %s" % NotRequired.__module__)
    print("[J2PY] Use Literal from %s" % Literal.__module__)
    print("[J2PY] Use Final from %s" % Final.__module__)
    print("[J2PY] Use TypeIs from %s" % TypeIs.__module__)
